head.script:
// 샘플에 직접 유효성 설정
scwin.tData = {
    "description" : "[radio > M > deleteItem]<br/>컴포넌트에서 특정 아이템을 제거합니다.",
    "validation" : [        
        "index(필수) 파라미터로 제거하려는 아이템의 인덱스를 숫자로 설정합니다.",
        "아이템의 인덱스는 0 부터 시작합니다.",
        "설정한 인덱스 위치의 아이템이 제거되고 이후 아이템의 인덱스가 하나씩 감소합니다.",
        "제거된 아이템의 정보를 result 객체로 반환합니다.",
        "파라미터의 인덱스값이 유효하지 않은 경우 undefined 또는 null 값을 반환합니다.",
        "result.label 속성값으로 제거된 아이템의 Label 값을 갖습니다.",
        "result.value 속성값으로 제거된 아이템의 value 값을 갖습니다.",
        "DataCollection 바인딩으로 아이템이 정의된 경우 제거된 아이템은 DataCollection 에 반영되지 않습니다.",
    ]
} 



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // target 생성    
    $c.gcm.createBasicRadio('');
}



scwin.btn_getDataList_onclick = function (e) {
	// let rsData  = dlt_ref.getAllJSON();
    let rsData = gdl_radio.getAllJSON();

    for(var i = 0; i < rsData.length; i++) {        
        wf_body_bottom.getObj("scwin").setReturnValue("label 값 : " + rsData[i].label);
    }
};



scwin.btn_deleteItem_onclick = function (e) {
    let rtn = '';
    let index = par_index.getValue();

    rtn = target1.deleteItem(index);

    wf_body_bottom.getObj("scwin").setReturnValue("obj : " + rtn);
    wf_body_bottom.getObj("scwin").setReturnValue("label : " + rtn.label);
    wf_body_bottom.getObj("scwin").setReturnValue("value : " + rtn.value);
};
